import { expect, test, vi, describe, beforeEach } from 'vitest';
import UserDashboard from './UserDashboard';
import React from 'react';

// Mock global fetch
const fetchMock = vi.fn();
global.fetch = fetchMock;

describe('UserDashboard', () => {
  beforeEach(() => {
    fetchMock.mockReset();
  });

  test('fetches preferences with no-store cache', async () => {
    const mockData = { theme: 'dark', notifications: true };
    fetchMock.mockResolvedValue({
      ok: true,
      json: async () => mockData,
    });

    await UserDashboard();

    expect(fetchMock).toHaveBeenCalledWith('https://api.example.com/user/preferences', {
      cache: 'no-store',
    });
  });

  test('handles fetch error gracefully', async () => {
    fetchMock.mockResolvedValue({
      ok: false,
    });

    const result = await UserDashboard();

    // We expect it to return a React element (error state)
    // Since we can't easily inspect the rendered output without rendering it,
    // we'll at least verify the fetch call happened.
    expect(fetchMock).toHaveBeenCalled();

    // Check if the returned element is the error message
    // The error return has a <p className="error">
    expect((result as any).props.children[1].props.className).toBe('error');
  });

  test('handles network error gracefully', async () => {
    fetchMock.mockRejectedValue(new Error('Network error'));

    const result = await UserDashboard();

    expect(fetchMock).toHaveBeenCalled();
    expect((result as any).props.children[1].props.className).toBe('error');
  });
});

